import sys

def prime_factorize(n, factor):
    base = 2
    exp = 0
    while base < n:
        while n % base == 0:
            n = n // base
            exp += 1
        if exp > 0:
            factor[base] = factor.get(base, 0) + exp
        base += 1
        exp = 0
    if n > 1:
        factor[base] = factor.get(base, 0) + 1
    return factor

