def f(s):
    d = defaultdict(int)
    for c in s:
        d[c] += 1
    return d

def g(d1, d2):
    new_d = {}
    ks = set(d1.keys()).intersection(set(d2.keys()))
    for k in ks:
        new_d[k] = min(d1[k], d2[k])
    return new_d

